import java.math.BigInteger

fun main() {
    val (l, r) = readLine()!!.split(" ").map { it.toLong() }
    var lVal = l
    var rVal = r

    val w = BooleanArray(99)
    val W = BooleanArray(99)
    var q = 0
    var Q = 0

    while (lVal != 0L) {
        w[q] = (lVal and 1L) != 0L
        lVal = lVal shr 1
        q++
    }
    while (rVal != 0L) {
        W[Q] = (rVal and 1L) != 0L
        rVal = rVal shr 1
        Q++
    }

    var p = 0
    for (i in Q downTo 0) {
        if (w[i] != W[i]) {
            p = i + 1
            break
        }
    }

    val ans = (1L shl p) - 1L
    print(ans)
}

